417	// CreateHandover 由交班班次向同岗位接班班次发起交接。
418	// 重复向同一接班班次发起返回已有记录（ErrHandoverExists）；该承诺在接班班次
419	// 随后结束、事项已在后续班次关闭或继续流转后仍然成立，返回保存的原交接内容，
420	// 不重新挑选清单、不重新接收或移动事项、不追加经过。改换接班对象报
421	// ErrHandoverTarget 并指出原接班班次，无论新对象是否结束都不产生第二条交接。
422	// 不存在的班次编号与交给自身始终按各自错误拒绝；同岗位及接班班次尚未结束等
423	// 要求仅对首次发起生效。
424	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
425		fromShiftID = clean(fromShiftID)
426		toShiftID = clean(toShiftID)
427	
428		var result Handover
429		err := svc.store.mutate(func(d *Data) error {
430			from, _ := findShift(d, fromShiftID)
431			to, _ := findShift(d, toShiftID)
432			if from == nil {
433				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
434			}
435			if to == nil {
436				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
437			}
438			if from.ID == to.ID {
439				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
440			}
441			// 同一交班班次只能指定一个接班对象。重复发起（包括接班班次随后已
442			// 结束、事项已在后续班次关闭或继续流转的情况）一律返回保存的原记录，
443			// 不重新接收事项、不追加经过；改换为另一个确实存在的接班对象（无论其
444			// 是否结束、是否同岗位）都按改换对象报错并指出原接班班次，且不能生成
445			// 第二条交接。该判定先于同岗位、接班班次状态等首次发起校验；编号不
446			// 存在与交给自身的校验仍在其前。
447			for i := range d.Handovers {
448				if d.Handovers[i].FromShiftID == from.ID {
449					existing := &d.Handovers[i]
450					result = *existing
451					if existing.ToShiftID != to.ID {
452						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
453							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
454					}
455					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
456				}
457			}
458	
459			if from.Position != to.Position {
460				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
461					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
462			}
463	
464			// 以下为首次发起的要求：接班班次尚未结束、开始时间不早于交班班次、
465			// 交班班次已经结束，重叠区间须有说明。
466			if to.Closed {
467				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
468			}
469			if to.Start.Before(from.Start) {
470				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
471					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
472					from.ID, from.Start.Format(time.RFC3339))
473			}
474			if !from.Closed {
475				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
476					ErrShiftNotClosed, from.ID)
477			}
478			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasNote(d, from.ID, to.ID) {
479				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
480					ErrOverlap, from.ID, to.ID)
481			}
482	
483			entries := []HandoverEntry{}
484			for i := range d.Items {
485				it := &d.Items[i]
486				if it.CurrentShiftID == from.ID && !it.Closed {
487					entries = append(entries, HandoverEntry{
488						ItemID:      it.ID,
489						Content:     it.Content,
490						Severity:    it.Severity,
491						Constraints: it.Constraints,
492						FollowOwner: it.FollowOwner,
493						Status:      EntryPending,
494					})
495				}
496			}
497			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
498	
499			d.HandoverSeq++
500			now := svc.now()
501			h := Handover{
502				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
503				Position:    from.Position,
504				FromShiftID: from.ID,
505				ToShiftID:   to.ID,
506				CreatedAt:   now,
507				Entries:     entries,
508			}
509			if len(entries) == 0 {
510				// 空清单直接完成。
511				h.CompletedAt = &now
512			}
513			d.Handovers = append(d.Handovers, h)
514			result = h
515			return nil
516		})
517		return result, err
518	}
