713	// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
714	// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
715	// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
716	// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
717	// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
718	// 交接编号排列。同一次接收若已出现在事项历史里只展示一次。只读查询，
719	// 不改变事项、交接进度或班次结束时记录。
720	func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
721		itemID = clean(itemID)
722		d := &svc.store.data
723		it, _ := findItem(d, itemID)
724		if it == nil {
725			return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
726		}
727		j := ItemJourney{Item: *it}
728	
729		// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
730		// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
731		// 该轮重新提交、后续处理）。
732		type keyedEvent struct {
733			ev    JourneyEvent
734			group string // "" 表示事项自身事件，否则为交接编号
735			ord   int    // 同一（时刻、分组）内的先后
736		}
737		var events []keyedEvent
738		seq := 0
739		add := func(ev JourneyEvent, group string) {
740			events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
741			seq++
742		}
743	
744		// received 事件与交接中的接收处理是同一次接收，只展示一次（以交接事件
745		// 展示，信息更全）；匹配不上的旧数据 received 事件仍原样保留。
746		receivedUsed := make([]bool, len(it.Events))
747	
748		hs := append([]Handover(nil), d.Handovers...)
749		sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
750		for k := range hs {
751			h := &hs[k]
752			e, _ := findEntry(h, itemID)
753			if e == nil {
754				continue
755			}
756			j.HasHandovers = true
757			j.Results = append(j.Results, EntryView{
758				HandoverID: h.ID,
759				FromShift:  h.FromShiftID,
760				ToShift:    h.ToShiftID,
761				Entry:      *e,
762			})
763	
764			// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
765			add(JourneyEvent{
766				At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
767				Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
768			}, h.ID)
769			for _, r := range e.Rounds {
770				add(JourneyEvent{
771					At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
772					Kind: "return", Operator: r.ReturnOperator,
773					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
774					RoundSeq: r.Seq, Reason: r.Reason,
775				}, h.ID)
776				if r.ResubmittedAt != nil {
777					add(JourneyEvent{
778						At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
779						Kind: "resubmit", Operator: r.SupplementOperator,
780						HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
781						RoundSeq: r.Seq, Supplement: r.Supplement,
782						SupplementOperator: r.SupplementOperator, SupplementAt: r.SupplementAt,
783					}, h.ID)
784				}
785			}
786			if e.Status.Received() {
787				kind := "confirm"
788				if e.Status == EntryTracking {
789					kind = "track"
790				}
791				ev := JourneyEvent{
792					Kind: kind, Operator: e.Operator,
793					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
794					TrackingNote: e.TrackingNote,
795					// 继续跟踪当时指定的后续负责人取自交接记录快照，
796					// 之后修改事项负责人不改变这里的历史值。
797					FollowOwner: e.FollowOwner,
798				}
799				// 处理时间缺失或为旧数据零值时仍保留该处理事件，
800				// 时间标为未记录，排在有真实时间的事件之后。
801				if validProcessedAt(e.ProcessedAt) {
802					ev.At, ev.TimeKnown = *e.ProcessedAt, true
803				}
804				add(ev, h.ID)
805				if validProcessedAt(e.ProcessedAt) {
806					for i := range it.Events {
807						iev := &it.Events[i]
808						if iev.Kind == "received" && !receivedUsed[i] &&
809							iev.At.Equal(*e.ProcessedAt) && iev.Operator == e.Operator {
810							receivedUsed[i] = true
811							break
812						}
813					}
814				}
815			}
816		}
817	
818		// 事项自身历史：建立、修改、关闭原样保留；未被交接接收事件覆盖的
819		// received 事件（旧数据）也保留。
820		for i, iev := range it.Events {
821			if iev.Kind == "received" && receivedUsed[i] {
822				continue
823			}
824			add(JourneyEvent{
825				At: iev.At, TimeKnown: !iev.At.IsZero(),
826				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
827			}, "")
828		}
829	
830		sort.SliceStable(events, func(i, k int) bool {
831			a, b := events[i], events[k]
832			if a.ev.TimeKnown != b.ev.TimeKnown {
833				return a.ev.TimeKnown
834			}
835			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
836				return a.ev.At.Before(b.ev.At)
837			}
838			if a.group != b.group {
839				return a.group < b.group
840			}
841			return a.ord < b.ord
842		})
843		for _, ke := range events {
844			j.Events = append(j.Events, ke.ev)
845		}
846		return j, nil
847	}
848	
849	// GetHandover 按编号查询交接。
850	func (svc *Service) GetHandover(id string) (Handover, error) {
851		h, _ := findHandover(&svc.store.data, clean(id))
852		if h == nil {
853			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
854		}
855		return *h, nil
856	}
857	
858	// ListHandovers 返回全部交接记录，按编号排序。
859	func (svc *Service) ListHandovers() []Handover {
860		out := append([]Handover(nil), svc.store.data.Handovers...)
861		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
862		return out
863	}
864	
865	// OverlapNotes 返回涉及指定班次的全部重叠说明。
866	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
867		shiftID = clean(shiftID)
868		out := []OverlapNote{}
869		for _, n := range svc.store.data.Notes {
870			if n.ShiftA == shiftID || n.ShiftB == shiftID {
871				out = append(out, n)
872			}
873		}
874		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
875		return out
876	}
877	
878	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
879	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
880	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
881	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
882		shiftID = clean(shiftID)
883		d := &svc.store.data
884		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
885		sh, _ := findShift(d, shiftID)
886		if sh == nil {
887			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
888		}
889		rep.Shift = *sh
890	
891		for _, n := range d.Notes {
892			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
893				rep.OverlapNotes = append(rep.OverlapNotes, n)
894			}
895		}
896		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
897	
898		switch {
899		case !sh.Closed:
900			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
901			rep.Items = currentItemsOfShift(d, sh.ID)
902		case sh.CloseRecord != nil:
903			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
904			rep.ItemsAtClose = true
905			rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
906			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
907			for _, s := range rep.CloseItems {
908				if it, _ := findItem(d, s.ItemID); it != nil {
909					rep.LatestItems[s.ItemID] = *it
910				}
911			}
912		default:
913			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
914			rep.HistoryIncomplete = true
915			rep.Items = currentItemsOfShift(d, sh.ID)
916		}
917		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
918	
919		for i := range d.Handovers {
920			h := &d.Handovers[i]
921			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
922			if !involved {
923				continue
924			}
925			if h.FromShiftID == sh.ID {
926				cp := *h
927				rep.Outgoing = &cp
928			}
929			if h.ToShiftID == sh.ID {
930				rep.Incoming = append(rep.Incoming, *h)
931			}
932			for j := range h.Entries {
933				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
934					HandoverID: h.ID,
935					FromShift:  h.FromShiftID,
936					ToShift:    h.ToShiftID,
937					Entry:      h.Entries[j],
938				})
939			}
940		}
941		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
942		for k := range rep.Results {
943			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
944		}
945		return rep, nil
946	}
