1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	const displayTime = "2006-01-02 15:04:05 -07:00"
11	
12	func fmtTime(t time.Time) string { return t.Format(displayTime) }
13	
14	func fmtTimePtr(t *time.Time) string {
15		if t == nil {
16			return "-"
17		}
18		return fmtTime(*t)
19	}
20	
21	// FormatShift 格式化班次摘要。
22	func FormatShift(sh Shift) string {
23		state := "进行中"
24		if sh.Closed {
25			state = "已结束 " + fmtTimePtr(sh.ClosedAt)
26		}
27		return fmt.Sprintf("%s  岗位=%s  负责人=%s  %s ~ %s  [%s]",
28			sh.ID, sh.Position, sh.Owner, fmtTime(sh.Start), fmtTime(sh.End), state)
29	}
30	
31	// FormatItem 格式化事项及其关闭情况与历史。
32	func FormatItem(it Item) string {
33		var b strings.Builder
34		writeItemHeader(&b, it)
35		if len(it.Events) > 0 {
36			b.WriteString("  历史：\n")
37			for _, ev := range it.Events {
38				who := ""
39				if ev.Operator != "" {
40					who = " 操作人=" + ev.Operator
41				}
42				detail := ""
43				if ev.Detail != "" {
44					detail = " " + ev.Detail
45				}
46				fmt.Fprintf(&b, "    - %s %s%s%s\n", fmtTime(ev.At), ev.Kind, who, detail)
47			}
48		}
49		return b.String()
50	}
51	
52	// writeItemHeader 输出事项的最新内容、严重程度、限制条件、后续负责人、
53	// 当前所在班次、关闭情况和流经班次。
54	func writeItemHeader(b *strings.Builder, it Item) {
55		state := "未关闭"
56		if it.Closed {
57			state = fmt.Sprintf("已关闭（%s 于 %s）", it.CloseOperator, fmtTimePtr(it.ClosedAt))
58		}
59		fmt.Fprintf(b, "%s  严重程度=%s  当前班次=%s  原始班次=%s  [%s]\n",
60			it.ID, it.Severity.Label(), it.CurrentShiftID, it.OriginShiftID, state)
61		fmt.Fprintf(b, "  内容：%s\n", it.Content)
62		fmt.Fprintf(b, "  限制条件：%s\n", dashIfEmpty(it.Constraints))
63		fmt.Fprintf(b, "  后续负责人：%s\n", it.FollowOwner)
64		fmt.Fprintf(b, "  流经班次：%s\n", strings.Join(it.ShiftIDs, " -> "))
65	}
66	
67	func dashIfEmpty(s string) string {
68		if s == "" {
69			return "-"
70		}
71		return s
72	}
73	
74	// whoIfRecorded 展示操作人，未记录时明确标为未记录，不以其他人代替。
75	func whoIfRecorded(s string) string {
76		if s == "" {
77			return "未记录"
78		}
79		return s
80	}
81	
82	// fmtTimePtrIfRecorded 展示时间指针，缺失时明确标为未记录。
83	func fmtTimePtrIfRecorded(t *time.Time) string {
84		if t == nil {
85			return "未记录"
86		}
87		return fmtTimeIfRecorded(*t)
88	}
89	
90	// fmtTimeIfRecorded 展示时间值，旧数据零值（0001-01-01T00:00:00Z）时
91	// 明确标为未记录，不显示公元元年日期。
92	func fmtTimeIfRecorded(t time.Time) string {
93		if t.IsZero() {
94			return "未记录"
95		}
96		return fmtTime(t)
97	}
98	
99	// fmtProcessedAtIfRecorded 展示处理时间，缺失（nil）或旧数据零值
100	// （0001-01-01T00:00:00Z）时明确标为未记录，不推测补齐。
101	func fmtProcessedAtIfRecorded(t *time.Time) string {
102		if t == nil || t.IsZero() {
103			return "未记录"
104		}
105		return fmtTime(*t)
106	}
107	
108	// entryCurrentResultLabel 是交接当前结果在事项处理经过查询中的展示名。
109	func entryCurrentResultLabel(s EntryStatus) string {
110		switch s {
111		case EntryPending:
112			return "待处理（接班人尚未处理）"
113		case EntryReturned:
114			return "退回（等待交班人补充）"
115		case EntryConfirmed:
116			return "确认接收"
117		case EntryTracking:
118			return "继续跟踪（已接收）"
119		}
120		return string(s)
121	}
122	
123	// FormatJourneyEvent 格式化处理经过中的单条记录。交接相关记录带有交接
124	// 编号与交班、接班班次；缺少的人名或时间明确标为未记录，不推测补齐。
125	func FormatJourneyEvent(ev JourneyEvent) string {
126		when := "未记录"
127		if ev.TimeKnown {
128			when = fmtTime(ev.At)
129		}
130		who := whoIfRecorded(ev.Operator)
131		where := ""
132		if ev.HandoverID != "" {
133			where = fmt.Sprintf("交接 %s（%s -> %s）", ev.HandoverID, ev.FromShift, ev.ToShift)
134		}
135		switch ev.Kind {
136		case "created":
137			return when + " 事项建立"
138		case "updated":
139			return fmt.Sprintf("%s 修改：%s", when, ev.Detail)
140		case "closed":
141			return fmt.Sprintf("%s 关闭 操作人=%s", when, who)
142		case "received":
143			return fmt.Sprintf("%s 接收 操作人=%s %s", when, who, ev.Detail)
144		case "handover-init":
145			// 交接发起不记录操作人，始终显示未记录，不以班次负责人代替。
146			return fmt.Sprintf("%s %s发起交接 操作人=%s", when, where, who)
147		case "return":
148			return fmt.Sprintf("%s %s第%d次退回 操作人=%s 原因=%s",
149				when, where, ev.RoundSeq, who, ev.Reason)
150		case "resubmit":
151			return fmt.Sprintf("%s %s第%d次重新提交 补充说明=%s 补充人=%s 补充时间=%s",
152				when, where, ev.RoundSeq, dashIfEmpty(ev.Supplement),
153				whoIfRecorded(ev.SupplementOperator), fmtTimePtrIfRecorded(ev.SupplementAt))
154		case "confirm":
155			return fmt.Sprintf("%s %s确认接收 操作人=%s", when, where, who)
156		case "track":
157			return fmt.Sprintf("%s %s继续跟踪 操作人=%s 跟踪说明=%s 后续负责人=%s",
158				when, where, who, dashIfEmpty(ev.TrackingNote), dashIfEmpty(ev.FollowOwner))
159		}
160		return when + " " + ev.Kind
161	}
162	
163	// FormatItemJourney 格式化凭事项编号查询得到的完整处理经过：开头为事项
164	// 最新状态，随后是合并事项自身历史与各次交接经过的时间线，最后列出该事项
165	// 在每次交接中的当前处理结果；尚未参与交接的显示暂无交接记录。
166	func FormatItemJourney(j ItemJourney) string {
167		var b strings.Builder
168		writeItemHeader(&b, j.Item)
169	
170		b.WriteString("  处理经过：\n")
171		if len(j.Events) == 0 {
172			b.WriteString("    （暂无记录）\n")
173		}
174		for _, ev := range j.Events {
175			b.WriteString("    - " + FormatJourneyEvent(ev) + "\n")
176		}
177	
178		b.WriteString("  交接当前结果：\n")
179		if !j.HasHandovers {
180			b.WriteString("    暂无交接记录\n")
181		}
182		for _, r := range j.Results {
183			operator, processedAt := "尚未处理", "尚未处理"
184			if r.Entry.Status != EntryPending {
185				// 已有处理结果（确认接收/继续跟踪/退回）时如实展示：处理人与
186				// 处理时间各自独立，缺失的明确标为未记录，不连带隐藏已保存的
187				// 处理人，也不把已处理结果显示成尚未处理。
188				operator = whoIfRecorded(r.Entry.Operator)
189				processedAt = fmtProcessedAtIfRecorded(r.Entry.ProcessedAt)
190			}
191			fmt.Fprintf(&b, "    交接 %s（%s -> %s）当前结果：%s；处理人=%s；处理时间=%s\n",
192				r.HandoverID, r.FromShift, r.ToShift,
193				entryCurrentResultLabel(r.Entry.Status), operator, processedAt)
194		}
195		return b.String()
196	}
197	
198	// FormatCloseItem 格式化班次结束时冻结的事项记录，并与最新状态对照。
199	func FormatCloseItem(snap CloseItemSnapshot, latest *Item) string {
200		var b strings.Builder
201		state := "结束时未关闭"
202		if snap.Closed {
203			state = fmt.Sprintf("结束时已关闭（%s 于 %s）", snap.CloseOperator, fmtTimePtr(snap.ClosedAt))
204		}
205		fmt.Fprintf(&b, "%s  严重程度=%s  %s\n", snap.ItemID, snap.Severity.Label(), state)
206		fmt.Fprintf(&b, "  内容：%s\n", snap.Content)
207		fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(snap.Constraints))
208		fmt.Fprintf(&b, "  结束时后续负责人：%s\n", snap.FollowOwner)
209		if latest == nil {
210			b.WriteString("  最新状态：事项记录已不存在\n")
211			return b.String()
212		}
213		closeState := "未关闭"
214		if latest.Closed {
215			closeState = fmt.Sprintf("已关闭（%s 于 %s）", latest.CloseOperator, fmtTimePtr(latest.ClosedAt))
216		}
217		fmt.Fprintf(&b, "  最新状态：当前所在班次=%s  最新负责人=%s  最新关闭情况=%s\n",
218			latest.CurrentShiftID, latest.FollowOwner, closeState)
219		return b.String()
220	}
221	
222	// FormatOverlapNote 格式化重叠说明。
223	func FormatOverlapNote(n OverlapNote) string {
224		return fmt.Sprintf("%s  岗位=%s  班次 %s <-> %s  %s\n  说明：%s",
225			n.ID, n.Position, n.ShiftA, n.ShiftB, fmtTime(n.CreatedAt), n.Note)
226	}
227	
228	// FormatEntry 格式化交接单项当前结果与历次退回、补充说明。
229	func FormatEntry(e HandoverEntry) string {
230		var b strings.Builder
231		fmt.Fprintf(&b, "%s  [%s]  严重程度=%s  后续负责人=%s\n",
232			e.ItemID, e.Status.Label(), e.Severity.Label(), e.FollowOwner)
233		fmt.Fprintf(&b, "  原文：%s\n", e.Content)
234		fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(e.Constraints))
235		// 是否处理过以已保存的处理结果为准，不以处理时间是否保存为准：确认接收、
236		// 继续跟踪与退回都属于已经发生的处理。处理人与处理时间各自独立展示，缺少
237		// 其中一个不能隐藏另一个：人名缺失明确标为未记录，时间缺失或为旧数据零值
238		// （0001-01-01T00:00:00Z）同样标为未记录，不以班次负责人、交接发起时间或
239		// 退回历史中的时间代替；真正待处理（含退回后已补充重新提交、等待接班人再次
240		// 处理）的事项才显示尚未处理。
241		if e.Status == EntryPending {
242			b.WriteString("  最后处理：尚未处理（等待接班人处理）；处理人=尚未处理；处理时间=尚未处理\n")
243		} else {
244			fmt.Fprintf(&b, "  最后处理：处理人=%s；处理时间=%s\n",
245				whoIfRecorded(e.Operator), fmtProcessedAtIfRecorded(e.ProcessedAt))
246		}
247		if e.Status == EntryTracking || e.TrackingNote != "" {
248			fmt.Fprintf(&b, "  跟踪说明：%s\n", dashIfEmpty(e.TrackingNote))
249			fmt.Fprintf(&b, "  跟踪后续负责人：%s\n", dashIfEmpty(e.FollowOwner))
250		}
251		for _, r := range e.Rounds {
252			fmt.Fprintf(&b, "  第%d次退回：%s 操作人=%s 原因=%s\n",
253				r.Seq, fmtTimeIfRecorded(r.ReturnedAt),
254				whoIfRecorded(r.ReturnOperator), r.Reason)
255			if r.Supplement != "" {
256				fmt.Fprintf(&b, "    补充说明：%s 补充人=%s 补充时间=%s\n",
257					r.Supplement, whoIfRecorded(r.SupplementOperator),
258					fmtTimePtrIfRecorded(r.SupplementAt))
259			}
260			if r.ResubmittedAt != nil {
261				fmt.Fprintf(&b, "    已重新提交：%s\n", fmtTimePtrIfRecorded(r.ResubmittedAt))
262			}
263		}
264		return b.String()
265	}
266	
267	// FormatHandover 格式化完整交接记录。
268	func FormatHandover(h Handover) string {
269		var b strings.Builder
270		state := "未完成"
271		if h.Completed() {
272			state = "已完成 " + fmtTimePtrIfRecorded(h.CompletedAt)
273		}
274		fmt.Fprintf(&b, "%s  岗位=%s  %s -> %s  发起于 %s  [%s]  共%d项\n",
275			h.ID, h.Position, h.FromShiftID, h.ToShiftID,
276			fmtTimeIfRecorded(h.CreatedAt), state, len(h.Entries))
277		if len(h.Entries) == 0 {
278			b.WriteString("  （空清单，直接完成）\n")
279		}
280		for i := range h.Entries {
281			b.WriteString(indentLines(FormatEntry(h.Entries[i]), "  "))
282		}
283		return b.String()
284	}
285	
286	func indentLines(s, prefix string) string {
287		return prefix + strings.ReplaceAll(strings.TrimRight(s, "\n"), "\n", "\n"+prefix) + "\n"
288	}
289	
290	// FormatReport 格式化按班次查询的完整报告。
291	func FormatReport(rep ShiftReport) string {
292		var b strings.Builder
293		b.WriteString("班次 " + FormatShift(rep.Shift) + "\n")
294	
295		b.WriteString("\n重叠说明：\n")
296		if len(rep.OverlapNotes) == 0 {
297			b.WriteString("  （无）\n")
298		}
299		for _, n := range rep.OverlapNotes {
300			b.WriteString(indentLines(FormatOverlapNote(n), "  "))
301		}
302	
303		if rep.ItemsAtClose {
304			b.WriteString("\n事项（以下为结束时记录，冻结于该班结束成功时刻；后班的修改、关闭与交接不改变本记录）：\n")
305			if len(rep.CloseItems) == 0 {
306				b.WriteString("  （结束时没有事项）\n")
307			}
308			for _, s := range rep.CloseItems {
309				var latest *Item
310				if v, ok := rep.LatestItems[s.ItemID]; ok {
311					latest = &v
312				}
313				b.WriteString(indentLines(FormatCloseItem(s, latest), "  "))
314			}
315		} else {
316			if rep.HistoryIncomplete {
317				b.WriteString("\n事项（历史记录不完整，该班结束时未留下记录，以下为当前信息，不能视为结束时事实）：\n")
318			} else {
319				b.WriteString("\n事项：\n")
320			}
321			if len(rep.Items) == 0 {
322				b.WriteString("  （无）\n")
323			}
324			for _, it := range rep.Items {
325				b.WriteString(indentLines(FormatItem(it), "  "))
326			}
327		}
328	
329		b.WriteString("\n交班对象：\n")
330		if rep.Outgoing == nil {
331			b.WriteString("  （尚未发起交接）\n")
332		} else {
333			b.WriteString(indentLines(FormatHandover(*rep.Outgoing), "  "))
334		}
335	
336		b.WriteString("\n接班交接：\n")
337		if len(rep.Incoming) == 0 {
338			b.WriteString("  （无）\n")
339		}
340		for _, h := range rep.Incoming {
341			b.WriteString(indentLines(FormatHandover(h), "  "))
342		}
343	
344		b.WriteString("\n各项交接当前结果：\n")
345		if len(rep.Results) == 0 {
346			b.WriteString("  （无）\n")
347		}
348		ids := make([]string, 0, len(rep.Results))
349		for id := range rep.Results {
350			ids = append(ids, id)
351		}
352		sort.Strings(ids)
353		for _, id := range ids {
354			views := rep.Results[id]
355			for _, v := range views {
356				// 是否处理过以已保存的处理结果（状态）为准，与处理时间是否保存
357				// 无关：确认接收、继续跟踪、退回都算已处理。处理人与处理时间
358				// 分别独立展示，缺失的明确标为未记录，不用另一方或退回历史中的
359				// 信息代替；真正待处理（含退回后补充重新提交、等待接班人再次
360				// 处理）的事项才显示尚未处理。
361				operator, processedAt := "尚未处理", "尚未处理"
362				if v.Entry.Status != EntryPending {
363					operator = whoIfRecorded(v.Entry.Operator)
364					processedAt = fmtProcessedAtIfRecorded(v.Entry.ProcessedAt)
365				}
366				fmt.Fprintf(&b, "  事项 %s 交接 %s（%s -> %s）当前结果：%s；处理人=%s；处理时间=%s\n",
367					id, v.HandoverID, v.FromShift, v.ToShift,
368					v.Entry.Status.Label(), operator, processedAt)
369				for _, r := range v.Entry.Rounds {
370					fmt.Fprintf(&b, "    第%d次退回：操作人=%s 时间=%s 原因=%s\n",
371						r.Seq, whoIfRecorded(r.ReturnOperator),
372						fmtTimeIfRecorded(r.ReturnedAt), r.Reason)
373					if r.Supplement != "" {
374						fmt.Fprintf(&b, "      补充：%s（补充人=%s，补充时间=%s）\n",
375							r.Supplement, whoIfRecorded(r.SupplementOperator),
376							fmtTimePtrIfRecorded(r.SupplementAt))
377					}
378					if r.ResubmittedAt != nil {
379						fmt.Fprintf(&b, "      已重新提交：%s\n", fmtTimePtrIfRecorded(r.ResubmittedAt))
380					}
381				}
382			}
383		}
384		return b.String()
385	}
