// Completed 报告交接是否已完成。完成以清单中每一项都明确为确认接收或继续
// 跟踪为准：待处理、退回，以及结果缺失、为空或无法识别的项都使整条交接
// 未完成，不能仅凭没有待处理或退回项就认定完成；其他项全部已接收也不能
// 抵消单项的不确定结果。空清单直接完成。
func (h *Handover) Completed() bool {
	for i := range h.Entries {
		if !h.Entries[i].Status.Received() {
			return false
		}
	}
	return true
}

