package handover

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// 临时验证：不确定结果（缺失/为空/无法识别）的完成判断与展示。
func TestScratchUncertainResult(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "data.json")

	now := time.Date(2026, 10, 2, 8, 0, 0, 0, time.UTC)
	completedAt := now.Add(time.Hour)
	data := Data{
		ShiftSeq: 2, ItemSeq: 2, HandoverSeq: 1,
		Shifts: []Shift{
			{ID: "S001", Position: "调度", Owner: "张三", Start: now, End: now.Add(8 * time.Hour), Closed: true},
			{ID: "S002", Position: "调度", Owner: "李四", Start: now.Add(8 * time.Hour), End: now.Add(16 * time.Hour)},
		},
		Items: []Item{
			{ID: "I001", OriginShiftID: "S001", ShiftIDs: []string{"S001"}, CurrentShiftID: "S001", Content: "甲", Severity: SeverityNormal, FollowOwner: "王五"},
			{ID: "I002", OriginShiftID: "S001", ShiftIDs: []string{"S001", "S002"}, CurrentShiftID: "S002", Content: "乙", Severity: SeverityNormal, FollowOwner: "王五"},
			{ID: "I003", OriginShiftID: "S001", ShiftIDs: []string{"S001"}, CurrentShiftID: "S001", Content: "丙", Severity: SeverityNormal, FollowOwner: "王五"},
		},
		Handovers: []Handover{{
			ID: "H001", Position: "调度", FromShiftID: "S001", ToShiftID: "S002",
			CreatedAt: now, CompletedAt: &completedAt, // 旧记录里残留的完成时间，不能掩盖不确定结果
			Entries: []HandoverEntry{
				{ItemID: "I001", Content: "甲", Severity: SeverityNormal, FollowOwner: "王五", Status: ""},
				{ItemID: "I002", Content: "乙", Severity: SeverityNormal, FollowOwner: "王五", Status: EntryConfirmed, Operator: "李四", ProcessedAt: &now},
				{ItemID: "I003", Content: "丙", Severity: SeverityNormal, FollowOwner: "王五", Status: EntryStatus("archived")},
			},
		}},
	}
	raw, _ := json.Marshal(data)
	if err := os.WriteFile(path, raw, 0o644); err != nil {
		t.Fatal(err)
	}

	store, err := Open(path)
	if err != nil {
		t.Fatalf("应能正常打开: %v", err)
	}
	svc := NewService(store)

	h, err := svc.GetHandover("H001")
	if err != nil {
		t.Fatalf("应保留查询能力: %v", err)
	}
	if h.Completed() {
		t.Fatal("存在缺失/无法识别结果，交接不能算完成")
	}

	text := FormatHandover(h)
	for _, want := range []string{"[未完成]", "[处理结果未记录]", "处理结果无法识别（原值：archived）"} {
		if !strings.Contains(text, want) {
			t.Fatalf("交接展示缺少 %q：\n%s", want, text)
		}
	}
	if strings.Contains(text, "已完成") {
		t.Fatalf("残留的完成时间不能掩盖不确定结果：\n%s", text)
	}

	// 接班班次不能结束，且保持进行中、无结束记录。
	if _, err := svc.CloseShift("S002"); !errors.Is(err, ErrHandoverState) {
		t.Fatalf("应拒绝结束，got %v", err)
	} else if !strings.Contains(err.Error(), "仍有未确认接收的事项") {
		t.Fatalf("错误说明应指出未确认接收：%v", err)
	}
	sh, _ := svc.GetShift("S002")
	if sh.Closed || sh.ClosedAt != nil || sh.CloseRecord != nil {
		t.Fatalf("班次应保持进行中且无结束记录：%+v", sh)
	}

	// 交接结果、事项归属不被拒绝结束改变。
	h2, _ := svc.GetHandover("H001")
	if h2.Entries[1].Status != EntryConfirmed || h2.Entries[0].Status != "" {
		t.Fatalf("交接结果不应被改变：%+v", h2.Entries)
	}
	it, _ := svc.GetItem("I001")
	if it.CurrentShiftID != "S001" {
		t.Fatalf("事项归属不应改变：%+v", it)
	}

	// 两侧班次报告表达同一事实。
	for _, id := range []string{"S001", "S002"} {
		rep, err := svc.ShiftReport(id)
		if err != nil {
			t.Fatalf("班次 %s 报告应可查询: %v", id, err)
		}
		rt := FormatReport(rep)
		if !strings.Contains(rt, "处理结果未记录") || !strings.Contains(rt, "处理结果无法识别（原值：archived）") {
			t.Fatalf("班次 %s 报告应展示不确定结果：\n%s", id, rt)
		}
		if strings.Contains(rt, "已完成") {
			t.Fatalf("班次 %s 报告不能把该交接展示成已完成：\n%s", id, rt)
		}
	}

	// 事项处理经过中也不推测接收。
	j, err := svc.ItemJourney("I001")
	if err != nil {
		t.Fatal(err)
	}
	jt := FormatItemJourney(j)
	if !strings.Contains(jt, "当前结果：处理结果未记录") {
		t.Fatalf("处理经过应显示未记录结果：\n%s", jt)
	}
	for _, ev := range j.Events {
		if ev.Kind == "confirm" || ev.Kind == "track" {
			t.Fatalf("不能为不确定结果生成接收事件：%+v", ev)
		}
	}
}

