	if err != nil {
		t.Fatal(err)
	}
	jt := FormatItemJourney(j)
	if !strings.Contains(jt, "当前结果：处理结果未记录") {
		t.Fatalf("处理经过应显示未记录结果：\n%s", jt)
	}
	for _, ev := range j.Events {
		if ev.Kind == "confirm" || ev.Kind == "track" {
			t.Fatalf("不能为不确定结果生成接收事件：%+v", ev)
		}
	}
}
